struct pool_head *entry;
struct list *start;
unsigned int align;
unsigned int best_diff;
int thr __maybe_unused;

/* alignment of zero means type alignment */
if (!alignment)
	alignment = reg->type_align;

/* extend alignment if needed */
if (alignment < sizeof(void*))
	alignment = sizeof(void*);
else if (alignment & (alignment - 1)) {
	/* not power of two! round up to next power of two by filling
	 * all LSB in O(log(log(N))) then increment the result.
	 */
	int shift = 1;
	do {
		alignment |= alignment >> shift;
		shift *= 2;
	} while (alignment & (alignment + 1));
	alignment++;
}

if (reg->type_align && alignment < reg->type_align) {
	ha_alert("BUG in the code: at %s:%u, requested creation of pool '%s' aligned to %u "
		 "while type requires alignment of %u! Please report to developers. Aborting.\n",
		 reg->file, reg->line, name, alignment, reg->type_align);
	return NULL;
}

if (invalid_char(name)) {
	ha_alert("Pool '%s' declared at %s:%u contains invalid chars in its name and "
		 "cannot be registered. Please report to developers. Aborting.\n",
		 name, reg->file, reg->line);
	return NULL;
}

extra_mark = (pool_debugging & POOL_DBG_TAG) ? POOL_EXTRA_MARK : 0;
extra_caller = (pool_debugging & POOL_DBG_CALLER) ? POOL_EXTRA_CALLER : 0;
extra = extra_mark + extra_caller;

if (size > 0xFFFFFFFFULL || (size + extra) > 0xFFFFFFFFULL || (uint)(size + extra) < (uint)reg_size)
	goto ovf;

if (!(pool_debugging & POOL_DBG_NO_CACHE)) {
	/* we'll store two lists there, we need the room for this. Let's
	 * make sure it's always OK even when including the extra word
	 * that is stored after the pci struct.
	 */
	if (size + extra - extra_caller < sizeof(struct pool_cache_item))
		size = sizeof(struct pool_cache_item) + extra_caller - extra;
}

/* Now we know our size is set to the strict minimum possible. It may
 * be OK for elements allocated with an exact size (e.g. buffers), but
 * we're going to round the size up 16 bytes to merge almost identical
 * pools together. We only round up however when we add the debugging
 * tag since it's used to detect overflows. Otherwise we only round up
 * to the size of a word to preserve alignment.
 */
if (!(flags & MEM_F_EXACT)) {
	align = (pool_debugging & POOL_DBG_TAG) ? sizeof(void *) : 16;
	size  = ((size + align - 1) & -(ullong)align);
}

if (pool_debugging & POOL_DBG_BACKUP) {
	/* keep a full backup of the pool at release time. We need
	 * a word-aligned size, so it's fine to do it now.
	 */
	extra += size;
